61	    public static byte[] toByteArray(Object obj) throws IOException {
62	        byte[] bytes = null;
63	        ByteArrayOutputStream bos = null;
64	        ObjectOutputStream oos = null;
65	        try {
66	            bos = new ByteArrayOutputStream();
67	            oos = new ObjectOutputStream(bos);
68	            oos.writeObject(obj);
69	            oos.flush();
70	            bytes = bos.toByteArray();
71	        } finally {
72	            if (oos != null) {
73	                oos.close();
74	            }
75	            if (bos != null) {
76	                bos.close();
77	            }
78	        }
79	        return bytes;
80	    }
