40	    public static void generate(WorkerService workerService, String cluster, SimpleTextOutputStream out) {
41	        // only when worker service is initialized, we generate the stats. otherwise we will get bunch of NPE.
42	        if (workerService != null && workerService.isInitialized()) {
43	            // kubernetes runtime factory doesn't support stats collection through worker service
44	            if (workerService.getFunctionRuntimeManager().getRuntimeFactory() instanceof KubernetesRuntimeFactory) {
45	                return;
46	            }
47	
48	            Map<String, FunctionRuntimeInfo> functionRuntimes
49	                    = workerService.getFunctionRuntimeManager().getFunctionRuntimeInfos();
50	
51	            for (Map.Entry<String, FunctionRuntimeInfo> entry : functionRuntimes.entrySet()) {
52	                String fullyQualifiedInstanceName = entry.getKey();
53	                FunctionRuntimeInfo functionRuntimeInfo = entry.getValue();
54	                RuntimeSpawner functionRuntimeSpawner = functionRuntimeInfo.getRuntimeSpawner();
55	
56	                if (functionRuntimeSpawner != null) {
57	                    Runtime functionRuntime = functionRuntimeSpawner.getRuntime();
58	                    if (functionRuntime != null) {
59	                        try {
60	                            InstanceCommunication.MetricsData metrics = functionRuntime.getMetrics().get();
61	
62	                            String tenant = functionRuntimeInfo.getFunctionInstance()
63	                                    .getFunctionMetaData().getFunctionDetails().getTenant();
64	                            String namespace = functionRuntimeInfo.getFunctionInstance()
65	                                    .getFunctionMetaData().getFunctionDetails().getNamespace();
66	                            String name = functionRuntimeInfo.getFunctionInstance()
67	                                    .getFunctionMetaData().getFunctionDetails().getName();
68	                            int instanceId = functionRuntimeInfo.getFunctionInstance().getInstanceId();
69	                            String qualifiedNamespace = String.format("%s/%s", tenant, namespace);
70	
71	                            metric(out, cluster, qualifiedNamespace, name, FunctionStatsManager.PULSAR_FUNCTION_METRICS_PREFIX + FunctionStatsManager.PROCESS_LATENCY_MS, instanceId, metrics.getAvgProcessLatency());
72	                            metric(out, cluster, qualifiedNamespace, name, FunctionStatsManager.PULSAR_FUNCTION_METRICS_PREFIX + FunctionStatsManager.LAST_INVOCATION, instanceId, metrics.getLastInvocation());
73	                            metric(out, cluster, qualifiedNamespace, name, FunctionStatsManager.PULSAR_FUNCTION_METRICS_PREFIX + FunctionStatsManager.PROCESSED_SUCCESSFULLY_TOTAL, instanceId, metrics.getProcessedSuccessfullyTotal());
74	                            metric(out, cluster, qualifiedNamespace, name, FunctionStatsManager.PULSAR_FUNCTION_METRICS_PREFIX + FunctionStatsManager.PROCESSED_TOTAL, instanceId, metrics.getProcessedTotal());
75	                            metric(out, cluster, qualifiedNamespace, name, FunctionStatsManager.PULSAR_FUNCTION_METRICS_PREFIX + FunctionStatsManager.RECEIVED_TOTAL, instanceId, metrics.getReceivedTotal());
76	                            metric(out, cluster, qualifiedNamespace, name, FunctionStatsManager.PULSAR_FUNCTION_METRICS_PREFIX + FunctionStatsManager.SYSTEM_EXCEPTIONS_TOTAL, instanceId, metrics.getSystemExceptionsTotal());
77	                            metric(out, cluster, qualifiedNamespace, name, FunctionStatsManager.PULSAR_FUNCTION_METRICS_PREFIX + FunctionStatsManager.USER_EXCEPTIONS_TOTAL, instanceId, metrics.getUserExceptionsTotal());
78	
79	                            for (Map.Entry<String, Double> userMetricsMapEntry : metrics.getUserMetricsMap().entrySet()) {
80	                                String userMetricName = userMetricsMapEntry.getKey();
81	                                Double val = userMetricsMapEntry.getValue();
82	                                metric(out, cluster, qualifiedNamespace, name, FunctionStatsManager.PULSAR_FUNCTION_METRICS_PREFIX + userMetricName, instanceId, val);
83	                            }
84	
85	                        } catch (InterruptedException | ExecutionException e) {
86	                            log.warn("Failed to collect metrics for function instance {}",
87	                                    fullyQualifiedInstanceName, e);
88	                        }
89	                    }
90	                }
91	            }
92	        }
