132	    public FunctionStats calculateOverall() {
133	
134	        int nonNullInstances = 0;
135	        int nonNullInstancesOneMin = 0;
136	        for (FunctionInstanceStats functionInstanceStats : instances) {
137	            FunctionInstanceStats.FunctionInstanceStatsData functionInstanceStatsData = functionInstanceStats.getMetrics();
138	            receivedTotal += functionInstanceStatsData.receivedTotal;
139	            processedSuccessfullyTotal += functionInstanceStatsData.processedSuccessfullyTotal;
140	            systemExceptionsTotal += functionInstanceStatsData.systemExceptionsTotal;
141	            userExceptionsTotal += functionInstanceStatsData.userExceptionsTotal;
142	            if (functionInstanceStatsData.avgProcessLatency != null) {
143	                if (avgProcessLatency == null) {
144	                    avgProcessLatency = 0.0;
145	                }
146	                avgProcessLatency += functionInstanceStatsData.avgProcessLatency;
147	                nonNullInstances++;
148	            }
149	
150	            oneMin.receivedTotal += functionInstanceStatsData.oneMin.receivedTotal;
151	            oneMin.processedSuccessfullyTotal += functionInstanceStatsData.oneMin.processedSuccessfullyTotal;
152	            oneMin.systemExceptionsTotal += functionInstanceStatsData.oneMin.systemExceptionsTotal;
153	            oneMin.userExceptionsTotal += functionInstanceStatsData.oneMin.userExceptionsTotal;
154	            if (functionInstanceStatsData.oneMin.avgProcessLatency != null) {
155	                if (oneMin.avgProcessLatency == null) {
156	                    oneMin.avgProcessLatency = 0.0;
157	                }
158	                oneMin.avgProcessLatency += functionInstanceStatsData.oneMin.avgProcessLatency;
159	                nonNullInstancesOneMin++;
160	            }
161	
162	            if (functionInstanceStatsData.lastInvocation != null) {
163	                if (lastInvocation == null || functionInstanceStatsData.lastInvocation > lastInvocation) {
164	                    lastInvocation = functionInstanceStatsData.lastInvocation;
165	                }
166	            }
167	        }
168	
169	        // calculate average from sum
170	        if (nonNullInstances > 0) {
171	            avgProcessLatency = avgProcessLatency / nonNullInstances;
172	        }
